class MyApp extends App {
  public render() {
    const { Component, pageProps } = this.props;

    return (
      <StrictMode>
        <GlobalStyles>
          <ThemeProvider theme={theme}>
            <Container>
              <CssBaseline />
              <Component {...pageProps} />
            </Container>
          </ThemeProvider>
        </GlobalStyles>
      </StrictMode>
