const CuriosityStepper = ({ curiosities }: ICuriosityStepper) => {
  // const theme = useTheme();
  // const classes = useStyles(theme);

  const [activeStep, setActiveStep] = React.useState(0);

  function handleNext() {
    setActiveStep((prevActiveStep) => prevActiveStep + 1);
  }

  function handleBack() {
    setActiveStep((prevActiveStep) => prevActiveStep - 1);
  }

  return (
    <MobileStepper
      variant="progress"
      steps={curiosities.length}
      position="static"
      activeStep={activeStep}
      nextButton={
        <Button size="small" onClick={handleNext} disabled={activeStep === curiosities.length - 1}>
          Next
        </Button>
      }
      backButton={
        <Button size="small" onClick={handleBack} disabled={activeStep === 0}>
          Back
        </Button>
      }
    />
  );
};

export interface ICuriosityStepper {
  curiosities: ICuriosity[];
}

export default CuriosityStepper;

/**
 * Truncate a text longer than {maxLength} characters and append an ellipsis.
 */
export default (text: string, maxLength: number): string => {
  const ellipsis = '...';

  if (text.length < maxLength) return text;

  return text.substring(0, maxLength - ellipsis.length) + ellipsis;
};

